const assetPathPrefix = "https://www.figma.com/api/mcp/asset/1f3c6e00-87db-49b7-b33e-3d5763e85c5d";
const imgStartIcon = `${assetPathPrefix}/498c5.svg`;
const imgEndIcon = `${assetPathPrefix}/b0afd.svg`;

type ButtonProps = {
  className?: string;
  color?: "Inherit";
  endIcon?: React.ReactNode | null;
  endIcon1?: boolean;
  label?: boolean;
  size?: "S";
  startIcon?: React.ReactNode | null;
  startIcon1?: boolean;
  state?: "Enabled";
  variant?: "Contained";
};

function Button({ className, color = "Inherit", endIcon = null, endIcon1 = false, label = true, size = "S", startIcon = null, startIcon1 = false, state = "Enabled", variant = "Contained" }: ButtonProps) {
  return (
    <div className={className || "bg-[var(--global\\/inherit\\/bg,#212b36)] content-stretch flex gap-[var(--button\\/spacing,8px)] h-[var(--button\\/\\[small\\]--height,30px)] items-center justify-center min-w-[64px] px-[var(--button\\/\\[small\\]--px,12px)] relative rounded-[var(--button\\/radius,8px)]"} data-node-id="1667:129168">
      {startIcon1 &&
        (startIcon || (
          <div className="relative shrink-0 size-[18px]" data-node-id="1667:143014" data-name="start icon">
            <img alt="" className="absolute block inset-0 max-w-none size-full" src={imgStartIcon} />
          </div>
        ))}
      {label && (
        <p className="[word-break:break-word] font-['Segoe_UI:Bold'] leading-[22px] not-italic relative shrink-0 text-[12px] text-[color:var(--global\/inherit\/color,white)] whitespace-nowrap" data-node-id="1667:129170">
          Action
        </p>
      )}
      {endIcon1 &&
        (endIcon || (
          <div className="relative shrink-0 size-[18px]" data-node-id="1667:143017" data-name="end icon">
            <img alt="" className="absolute block inset-0 max-w-none size-full" src={imgEndIcon} />
          </div>
        ))}
    </div>
  );
}
